-- ----------------------------
-- Table structure for aem_evaluation_question
-- ----------------------------
DROP TABLE IF EXISTS `aem_evaluation_question`;
CREATE TABLE `aem_evaluation_question`  (
  `question_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '问题ID',
  `questionnaire_id` bigint(20) NOT NULL COMMENT '问卷ID',
  `question_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '问题类型（0单选 1多选 2评分 3文本）',
  `question_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '问题内容',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序号',
  `max_score` decimal(4, 1) NULL DEFAULT 10.0 COMMENT '最高评分（评分类型时有效）',
  `options_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '选项JSON（[{\"label\":\"非常满意\",\"value\":5},...]）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`question_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '评教问题表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aem_evaluation_question
-- ----------------------------

-- ----------------------------
-- Table structure for aem_evaluation_questionnaire
-- ----------------------------
DROP TABLE IF EXISTS `aem_evaluation_questionnaire`;
CREATE TABLE `aem_evaluation_questionnaire`  (
  `questionnaire_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '问卷ID',
  `semester_id` bigint(20) NOT NULL COMMENT '学期ID（关联brm_semester）',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '问卷标题',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '问卷说明',
  `question_count` int(11) NULL DEFAULT 0 COMMENT '题目数量',
  `full_score` decimal(5, 2) NULL DEFAULT 100.00 COMMENT '满分',
  `start_time` datetime NULL DEFAULT NULL COMMENT '评教开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '评教结束时间',
  `eval_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '评教状态（0未开始 1进行中 2已结束）',
  `is_anonymous` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '是否匿名（0实名 1匿名）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`questionnaire_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '评教问卷配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aem_evaluation_questionnaire
-- ----------------------------

-- ----------------------------
-- Table structure for aem_evaluation_result
-- ----------------------------
DROP TABLE IF EXISTS `aem_evaluation_result`;
CREATE TABLE `aem_evaluation_result`  (
  `result_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '结果ID',
  `questionnaire_id` bigint(20) NOT NULL COMMENT '问卷ID',
  `course_id` bigint(20) NULL DEFAULT NULL COMMENT '课程ID',
  `teacher_id` bigint(20) NULL DEFAULT NULL COMMENT '教师ID（关联brm_teacher）',
  `student_id` bigint(20) NULL DEFAULT NULL COMMENT '学生ID',
  `total_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '总评分',
  `eval_date` datetime NULL DEFAULT NULL COMMENT '评教时间',
  `comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评语建议',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  PRIMARY KEY (`result_id`) USING BTREE,
  INDEX `idx_eval_result_teacher_course`(`teacher_id` ASC, `course_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '评教结果表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aem_evaluation_result
-- ----------------------------

-- ----------------------------
-- Table structure for aem_exam_invigilation
-- ----------------------------
DROP TABLE IF EXISTS `aem_exam_invigilation`;
CREATE TABLE `aem_exam_invigilation`  (
  `invigilation_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '监考ID',
  `exam_id` bigint(20) NOT NULL COMMENT '考试ID',
  `classroom_id` bigint(20) NULL DEFAULT NULL COMMENT '教室ID（关联brm_classroom）',
  `teacher_id` bigint(20) NULL DEFAULT NULL COMMENT '监考教师ID（关联brm_teacher）',
  `exam_date` date NULL DEFAULT NULL COMMENT '考试日期',
  `start_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结束时间',
  `duty_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '职责（0主监考 1副监考 2巡考）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  PRIMARY KEY (`invigilation_id`) USING BTREE,
  INDEX `idx_exam_invigilation_exam`(`exam_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '监考分配表' ROW_FORMAT = Dynamic;

