DROP TABLE IF EXISTS `aem_exam_plan`;
CREATE TABLE `aem_exam_plan`  (
  `exam_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '考试ID',
  `exam_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考试名称',
  `semester_id` bigint(20) NOT NULL COMMENT '学期ID',
