  `mapping_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '映射ID',
  `config_id` bigint(20) NOT NULL COMMENT '算法配置ID（关联aem_gpa_algorithm_config）',
  `min_score` decimal(5, 2) NOT NULL COMMENT '最低分（含）',
  `max_score` decimal(5, 2) NOT NULL COMMENT '最高分（含）',
  `grade_point` decimal(3, 2) NOT NULL COMMENT '绩点值',
  `grade_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '等级（优秀/良好/中等/及格/不及格）',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序',
  PRIMARY KEY (`mapping_id`) USING BTREE,
  INDEX `idx_config_id`(`config_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'GPA分数段映射表' ROW_FORMAT = Dynamic;

