-- ----------------------------
-- Table structure for aem_grade_record
-- ----------------------------
DROP TABLE IF EXISTS `aem_grade_record`;
CREATE TABLE `aem_grade_record`  (
  `grade_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '成绩ID',
  `student_id` bigint(20) NOT NULL COMMENT '学生ID',
  `course_id` bigint(20) NULL DEFAULT NULL COMMENT '课程ID（关联tpm_course_library）',
  `semester_id` bigint(20) NOT NULL COMMENT '学期ID（关联brm_semester）',
  `exam_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '考试类型（0正考 1补考 2重修）',
  `regular_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '平时成绩',
  `exam_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '考试成绩',
  `total_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '总成绩',
  `grade_point` decimal(3, 1) NULL DEFAULT 0.0 COMMENT '绩点',
  `grade_level` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '等级（A优秀 B良好 C中等 D及格 F不及格）',
  `is_pass` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否通过（0否 1是）',
  `is_reviewed` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否已复核（0未复核 1已复核）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  PRIMARY KEY (`grade_id`) USING BTREE,
  INDEX `idx_grade_student_semester`(`student_id` ASC, `semester_id` ASC) USING BTREE,
  INDEX `idx_grade_course_semester`(`course_id` ASC, `semester_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23958 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成绩记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aem_grade_record
-- ----------------------------

-- ----------------------------
-- Table structure for aem_grade_review
-- ----------------------------
DROP TABLE IF EXISTS `aem_grade_review`;
CREATE TABLE `aem_grade_review`  (
  `review_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '复核ID',
  `grade_id` bigint(20) NOT NULL COMMENT '成绩ID',
  `student_id` bigint(20) NOT NULL COMMENT '学生ID',
  `course_id` bigint(20) NULL DEFAULT NULL COMMENT '课程ID',
  `original_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '原成绩',
  `new_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '新成绩',
  `review_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核原因',
  `review_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '复核类型（0成绩修改 1成绩复核）',
  `approve_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '审批状态（0待审 1通过 2驳回）',
  `approve_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批人',
  `approve_time` datetime NULL DEFAULT NULL COMMENT '审批时间',
  `approve_opinion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批意见',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  PRIMARY KEY (`review_id`) USING BTREE,
  INDEX `idx_grade_review_grade`(`grade_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成绩复核审批表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aem_grade_review
-- ----------------------------

-- ----------------------------
-- Table structure for aem_grade_statistics
-- ----------------------------
DROP TABLE IF EXISTS `aem_grade_statistics`;
CREATE TABLE `aem_grade_statistics`  (
  `stat_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '统计ID',
  `course_id` bigint(20) NULL DEFAULT NULL COMMENT '课程ID',
  `semester_id` bigint(20) NOT NULL COMMENT '学期ID',
  `class_id` bigint(20) NULL DEFAULT NULL COMMENT '班级ID（关联brm_class）',
  `total_students` int(11) NULL DEFAULT 0 COMMENT '总人数',
  `max_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '最高分',
  `min_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '最低分',
  `avg_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '平均分',
  `pass_count` int(11) NULL DEFAULT 0 COMMENT '通过人数',
  `fail_count` int(11) NULL DEFAULT 0 COMMENT '不及格人数',
  `pass_rate` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '通过率（%）',
  `excellent_count` int(11) NULL DEFAULT 0 COMMENT '优秀人数（90分以上）',
  `excellent_rate` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '优秀率（%）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  PRIMARY KEY (`stat_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10112 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成绩统计分析表' ROW_FORMAT = Dynamic;

