-- ----------------------------
-- Table structure for dis_interface_config
-- ----------------------------
DROP TABLE IF EXISTS `dis_interface_config`;
CREATE TABLE `dis_interface_config`  (
  `interface_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '接口ID',
  `system_id` bigint(20) NOT NULL COMMENT '所属系统ID',
  `interface_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '接口名称',
  `interface_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '接口编码',
  `request_method` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'GET' COMMENT '请求方式（GET POST PUT DELETE）',
  `request_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '请求路径',
  `request_template` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '请求模板（JSON格式参数定义）',
  `response_template` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应模板',
  `timeout_seconds` int(11) NULL DEFAULT 30 COMMENT '超时时间（秒）',
  `retry_count` int(11) NULL DEFAULT 0 COMMENT '重试次数',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接口描述',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  PRIMARY KEY (`interface_id`) USING BTREE,
  INDEX `idx_system_id`(`system_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 100 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '接口配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of dis_interface_config
-- ----------------------------

-- ----------------------------
-- Table structure for dis_sync_task
-- ----------------------------
DROP TABLE IF EXISTS `dis_sync_task`;
CREATE TABLE `dis_sync_task`  (
  `task_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务名称',
  `task_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务编码',
  `system_id` bigint(20) NOT NULL COMMENT '外部系统ID',
  `interface_id` bigint(20) NULL DEFAULT NULL COMMENT '接口ID',
  `cron_expression` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT 'Cron表达式',
  `last_execute_time` datetime NULL DEFAULT NULL COMMENT '上次执行时间',
  `next_execute_time` datetime NULL DEFAULT NULL COMMENT '下次执行时间',
  `execute_count` int(11) NULL DEFAULT 0 COMMENT '执行次数',
  `fail_count` int(11) NULL DEFAULT 0 COMMENT '失败次数',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0启用 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  PRIMARY KEY (`task_id`) USING BTREE,
  UNIQUE INDEX `uk_task_code`(`task_code` ASC) USING BTREE,
  INDEX `idx_system_id`(`system_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 100 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '数据同步任务表' ROW_FORMAT = Dynamic;

