DROP TABLE IF EXISTS `sam_certificate`;
CREATE TABLE `sam_certificate`  (
  `cert_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '证书ID',
  `student_id` bigint(20) NOT NULL COMMENT '学生ID（关联sam_student）',
  `cert_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '证书类型（0毕业证书 1学位证书 2结业证书）',
  `cert_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '证书编号',
  `cert_date` date NULL DEFAULT NULL COMMENT '发证日期',
  `major_id` bigint(20) NULL DEFAULT NULL COMMENT '专业ID（关联brm_major）',
  `education_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学历层次',
  `is_issued` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否发放（0否 1是）',
  `issue_date` date NULL DEFAULT NULL COMMENT '发放日期',
  `receiver` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '领取人',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`cert_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '证书编号管理表' ROW_FORMAT = Dynamic;

