-- ----------------------------
-- Table structure for sam_degree_review
-- ----------------------------
DROP TABLE IF EXISTS `sam_degree_review`;
CREATE TABLE `sam_degree_review`  (
  `review_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '审核ID',
  `student_id` bigint(20) NOT NULL COMMENT '学生ID（关联sam_student）',
  `graduation_review_id` bigint(20) NULL DEFAULT NULL COMMENT '毕业审核ID（关联sam_graduation_review）',
  `gpa` decimal(4, 2) NULL DEFAULT 0.00 COMMENT '平均绩点',
  `is_gpa_qualified` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '绩点是否合格（0否 1是）',
  `is_degree_course_qualified` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '学位课程是否合格（0否 1是）',
  `is_thesis_qualified` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '论文是否合格（0否 1是）',
  `degree_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学位类型（学士/硕士/博士）',
  `degree_field` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学位学科门类（工学/理学/管理学等）',
  `review_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '审核状态（0待审 1通过 2不通过）',
  `review_date` date NULL DEFAULT NULL COMMENT '审核日期',
  `reviewer` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `review_opinion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核意见',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  PRIMARY KEY (`review_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学位资格审核表' ROW_FORMAT = Dynamic;

