-- Records of sam_degree_review
-- ----------------------------

-- ----------------------------
-- Table structure for sam_graduation_procedure
-- ----------------------------
DROP TABLE IF EXISTS `sam_graduation_procedure`;
CREATE TABLE `sam_graduation_procedure`  (
  `procedure_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '手续ID',
  `student_id` bigint(20) NOT NULL COMMENT '学生ID（关联sam_student）',
  `library_cleared` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '图书馆清还（0未清 1已清）',
  `finance_cleared` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '财务结算（0未结 1已结）',
  `dormitory_cleared` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '宿舍退宿（0未退 1已退）',
  `card_returned` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '一卡通退还（0未退 1已退）',
  `procedure_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '手续状态（0未办理 1办理中 2已完成）',
  `complete_date` date NULL DEFAULT NULL COMMENT '完成日期',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`procedure_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '毕业离校手续表' ROW_FORMAT = Dynamic;

