-- Records of sam_status_change
-- ----------------------------

-- ----------------------------
-- Table structure for sam_student
-- ----------------------------
DROP TABLE IF EXISTS `sam_student`;
CREATE TABLE `sam_student`  (
  `student_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '学生ID',
  `student_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '学号',
  `student_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `gender` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '性别（0男 1女）',
  `birth_date` date NULL DEFAULT NULL COMMENT '出生日期',
  `id_card` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份证号',
  `major_id` bigint(20) NULL DEFAULT NULL COMMENT '专业ID（关联brm_major）',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '关联系统用户ID（关联sys_user）',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '院系ID（关联brm_department）',
  `class_id` bigint(20) NULL DEFAULT NULL COMMENT '班级ID（关联brm_class）',
  `enrollment_year` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入学年份（如2024级）',
  `education_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学历层次（本科/硕士/博士）',
  `student_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '学籍状态（0在读 1休学 2退学 3毕业 4转出 5保留学籍）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`student_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10822 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学生学籍信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sam_student
-- ----------------------------

-- ----------------------------
-- Table structure for sam_warning
-- ----------------------------
DROP TABLE IF EXISTS `sam_warning`;
CREATE TABLE `sam_warning`  (
  `warning_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '预警ID',
  `student_id` bigint(20) NOT NULL COMMENT '学生ID（关联sam_student）',
  `semester_id` bigint(20) NULL DEFAULT NULL COMMENT '学期ID（关联brm_semester）',
  `warning_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '预警类型（0成绩预警 1学分预警 2出勤预警 3综合预警）',
  `warning_level` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '预警级别（0一般 1严重 2高危）',
  `warning_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预警原因',
  `warning_date` date NULL DEFAULT NULL COMMENT '预警日期',
  `is_resolved` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否解除（0否 1是）',
  `resolve_date` date NULL DEFAULT NULL COMMENT '解除日期',
  `resolve_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '解除说明',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  PRIMARY KEY (`warning_id`) USING BTREE,
  INDEX `idx_warning_student_semester`(`student_id` ASC, `semester_id` ASC, `warning_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学籍预警表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sam_warning
-- ----------------------------

-- ----------------------------
-- Table structure for sam_warning_rule_config
-- ----------------------------
DROP TABLE IF EXISTS `sam_warning_rule_config`;
CREATE TABLE `sam_warning_rule_config`  (
  `rule_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '规则ID',
  `rule_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则代码(GPA_LOW/CREDIT_LOW/ATTENDANCE_LOW)',
  `rule_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则名称',
  `warning_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '预警类型（0成绩 1学分 2出勤 3综合）',
  `threshold_value` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '阈值',
  `warning_level` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '预警级别（0一般 1严重 2高危）',
  `message_template` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息模板',
  `is_enabled` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '是否启用（0否 1是）',
  `semester_id` bigint(20) NULL DEFAULT NULL COMMENT '适用学期ID（空表示所有）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`rule_id`) USING BTREE,
  UNIQUE INDEX `uk_rule_code`(`rule_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '预警规则配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sam_warning_rule_config
-- ----------------------------

-- ----------------------------
-- Table structure for sys_config
