INSERT INTO `portal_article` VALUES (1, 1, '我校召开2026年春季学期教学工作会议', '3月15日，学校在行政楼报告厅召开春季学期教学工作会议，部署新学期教学重点工作。', '<p>3月15日上午，学校在行政楼报告厅召开2026年春季学期教学工作会议。校领导、各学院院长、教学副院长及教务处相关人员参加了会议。</p><p>会议围绕新学期教学重点工作进行了部署，强调要持续推进教育教学改革，提升人才培养质量。</p>', '/upload/portal/article/2026/03/teaching-meeting.jpg', '长江大学新闻网', '宣传部', '2', '2026-03-15 10:00:00', '1', '1', 356, 1, '审核通过', '2026-03-14 16:00:00', 'admin', '2026-08-04 08:33:24', '', NULL, NULL);
INSERT INTO `portal_article` VALUES (2, 1, '长江大学与中科院签署战略合作协议', '我校与中国科学院签署战略合作协议，双方将在人才培养、科研合作等方面展开深度合作。', '<p>近日，长江大学与中国科学院在北京签署战略合作协议。</p><p>根据协议，双方将共建联合实验室，在石油工程、农业科学等优势学科领域开展深度科研合作，并联合培养高层次创新人才。</p>', '/upload/portal/article/2026/03/cas-agreement.jpg', '长江大学新闻网', '宣传部', '2', '2026-03-12 14:30:00', '0', '1', 528, 1, '审核通过', '2026-03-11 09:00:00', 'admin', '2026-08-04 08:33:24', '', NULL, NULL);
INSERT INTO `portal_article` VALUES (3, 2, '我校三项课题获国家自然科学基金重点项目立项', '2026年度国家自然科学基金重点项目评审结果公布，我校三项课题获立项资助。', '<p>近日，2026年度国家自然科学基金重点项目评审结果揭晓，我校石油工程学院、农学院、化学与环境工程学院各有一项课题获重点项目立项资助，直接经费合计超过800万元。</p>', '/upload/portal/article/2026/04/nsfc-projects.jpg', '科研处', '科研处', '2', '2026-04-20 09:00:00', '1', '1', 412, 1, '审核通过', '2026-04-19 17:00:00', 'admin', '2026-08-04 08:33:24', '', NULL, NULL);
INSERT INTO `portal_article` VALUES (4, 3, '关于2026年春季学期期末考试安排的通知', '各教学单位：2026年春季学期期末考试将于第18-19周进行，请做好相关准备工作。', '<p>各教学单位：</p><p>2026年春季学期期末考试将于第18-19周（6月23日-7月4日）进行。请各学院按照教务处统一安排，做好考试组织工作。</p><p>请各位同学认真复习备考，遵守考试纪律。</p>', NULL, '教务处', '教务处', '2', '2026-06-10 08:00:00', '1', '0', 892, 1, '审核通过', '2026-06-09 15:00:00', 'admin', '2026-08-04 08:33:24', '', NULL, NULL);
INSERT INTO `portal_article` VALUES (5, 3, '关于开展2026届毕业生学位授予工作的通知', '根据学位授予工作安排，现启动2026届毕业生学位授予审核工作。', '<p>各学院：</p><p>根据学校学位授予工作安排，现启动2026届毕业生学位授予审核工作。请各学院于6月30日前完成初审并将名单报送学位办。</p><p>联系人：张老师，电话：8060xxxx</p>', NULL, '学位办', '学位办', '2', '2026-06-05 10:00:00', '0', '0', 567, 1, '审核通过', '2026-06-04 14:00:00', 'admin', '2026-08-04 08:33:24', '', NULL, NULL);
INSERT INTO `portal_article` VALUES (6, 4, '春日长大：校园樱花季摄影展', '三月的长大校园，樱花盛开，春意盎然。让我们跟随镜头，感受校园春色。', '<p>三月的长江大学校园，樱花如雪，玉兰飘香。东西校区的樱花大道迎来了最美的季节。</p><p>本次摄影展收录了师生投稿的50余幅作品，展现了春日校园的独特魅力。</p>', '/upload/portal/article/2026/03/cherry-blossom.jpg', '校园记者团', '李明', '2', '2026-03-25 12:00:00', '0', '1', 723, 1, '审核通过', '2026-03-24 16:00:00', 'admin', '2026-08-04 08:33:24', '', NULL, NULL);
INSERT INTO `portal_article` VALUES (7, 5, '【湖北日报】长江大学：扎根荆楚大地 服务区域发展', '湖北日报整版报道我校服务区域经济社会发展的典型做法和成效。', '<p>近日，湖北日报以整版篇幅报道了长江大学扎根荆楚大地、服务区域经济社会发展的典型做法和显著成效。</p><p>报道从人才培养、科技创新、社会服务等多个维度，全面展示了学校近年来取得的成绩。</p>', '/upload/portal/article/2026/04/hubei-daily.jpg', '湖北日报', '转载', '2', '2026-04-08 09:30:00', '0', '0', 345, 1, '审核通过', '2026-04-07 17:00:00', 'admin', '2026-08-04 08:33:24', '', NULL, NULL);
INSERT INTO `portal_article` VALUES (8, 6, '【长大人】记国家奖学金获得者张同学：在科研路上笃定前行', '张同学，石油工程学院2022级博士生，获2025年度国家奖学金。', '<p>张同学，石油工程学院2022级博士研究生，师从王教授。在读期间发表SCI论文5篇，获2025年度研究生国家奖学金。</p><p>\"科研是一条漫长的路，但每一步都算数。\"这是张同学常挂在嘴边的话。</p>', '/upload/portal/article/2026/05/scholar-zhang.jpg', '学生工作处', '编辑部', '1', NULL, '0', '0', 0, NULL, NULL, NULL, 'admin', '2026-08-04 08:33:24', '', NULL, '待审核文章');
